BrowserAutomationStudioProject.Script:
section(1,1,1,0,function(){
section_start("\u007b\u0022n\u0022:\u0022BAS root and tracebacks folder\u0022\u007d", 990160001)!
/*Dat:*/
function basProjectDirectory(){
var _path={isPathSeparator:function(c){return c===47||c===92;},dirname:function(p){return JSON.parse(native("filesystem","fileinfo",p)).directory;}};
	var path = project_path();
	var c = '';
	var s = 0;
	var end = -1;
	for(var i = path.length - 1; i > -1; i--){
		if(_path.isPathSeparator(path.charCodeAt(i))){
			s++;
			if(c==='appsremote' || c==='appslocal'){
				end = i;
				break;
			}else{
				if(s===1){
					end = i;
					if(!(c==='project.xml')){
						break;
					};
				};
				if(s===2 && !(c==='engine')){
					break;
				};
				c = '';
			};
		}else{
			c = path.charAt(i) + c;
		};
	};
	return end===-1 ? _path.dirname(path) : path.slice(0, end);
};

/* Resolve shared modules independently from the runnable XML location. */
VAR_BAS_RUN_ROOT=String(basProjectDirectory()).split('\\').join('/').replace(/\/+$/,'');
VAR_BAS_SOURCE_FILE=String(project_path()).split('\\').join('/');
if(!VAR_BAS_SOURCE_FILE||!/[^/]+\.xml$/i.test(VAR_BAS_SOURCE_FILE))fail_user('BAS_SOURCE_FILE_UNAVAILABLE',false);
VAR_BAS_ROOT=(function(start){
  var candidate=start;
  for(var i=0;i<7;i++){
    var essentials=JSON.parse(native('filesystem','fileinfo',candidate+'/Essentials'));
    var data=JSON.parse(native('filesystem','fileinfo',candidate+'/data'));
    if(essentials.exists&&essentials.is_directory&&data.exists&&data.is_directory)return candidate;
    var parent=candidate.replace(/\/[^\/]+$/,'');
    if(parent===candidate)break;
    candidate=parent;
  }
  fail_user('BAS_SHARED_ROOT_NOT_FOUND',false);
  return '';
})(VAR_BAS_RUN_ROOT);
log("CRONOPUS_PROJECT_PATH="+project_path())
log("CRONOPUS_SHARED_ROOT="+VAR_BAS_ROOT)
section_end()!
})!
